function showRadio(){const box=$('radioInfo');box.replaceChildren();if(!radio){return;}
const release=firmwareRelease(radio.git);box.append(el('span',{class:'chip'},el('b',{},'DM-32'),el('span',{},`${t('firmware')} ${release || radio.git}`),el('span',{class:'dim'},buildTime(radio.build))));}
function setConnected(on){const b=$('btnConnect');b.querySelector('span').dataset.i18n=on?'disconnect':'connect';b.querySelector('span').textContent=t(on?'disconnect':'connect');$('btnRead').disabled=!on;$('btnWrite').disabled=!on;$('linkDot').classList.toggle('on',on);if(!on){radio=null;showRadio();status(t('notConnected'));}}
async function connect(){if(link?.connected){await link.close();link=null;setConnected(false);return;}
if(!RadioLink.supported()){toast(t(window.isSecureContext?'noSerial':'serialNeedsLocal'),8000);return;}
link=new RadioLink();try{await link.open();const info=await link.radioInfo();if(info.radioType!==11){toast(t('notOpenDmr'),6000);}
radio=info;showRadio();setConnected(true);status(t('connected'));}catch(e){toast(t('error')+': '+e.message,6000);await link?.close();link=null;setConnected(false);}}
async function readImage(){const img=new Uint8Array(L.IMAGE_SIZE).fill(0xFF);const total=L.REGIONS.reduce((n,r)=>n+(r.end-r.start),0);let done=0;for(const r of L.REGIONS){await link.readRegion(img,r.start,r.end,progress,done,total);done+=r.end-r.start;}
return img;}
async function readRadio(){status(t('reading'));try{await link.saveSettings();codeplug=new Codeplug(await readImage());selectedChannel=null;await link.closeScreen();status(t('readDone'));const oldest=Math.max(-1,...codeplug.satellites.map((s)=>satAgeDays(s)??-1));if(oldest>14){toast(t('radioOrbitsOld').replace('{n}',oldest),12000);}
render();}catch(e){toast(t('error')+': '+e.message,6000);status(t('error'));}finally{progress(0,0);}}
async function writeRadio(){try{const noTle=()=>codeplug.satellites.filter((s)=>!s.tle1.trim()||!s.tle2.trim());if(codeplug.satellites.length){if(!tleCatalog||tleCatalog.error){tleCatalog=null;await loadTleCatalog();}
refreshOrbits(tleCatalog.map);}
if(codeplug.satellitesDirty&&noTle().length){status(t('updateTle')+' …');await fetchTles(noTle());if(noTle().length&&!window.confirm(t('noTleWrite')+noTle().map((s)=>s.name).join(', '))){status('');return;}}
codeplug.store();status(t('reading'));await link.saveSettings();const onRadio=await readImage();const target=Uint8Array.from(onRadio);const ranges=L.ownedRanges(codeplug.channelsPerZone);if(codeplug.settings.dirty&&codeplug.settings.valid){ranges.push([SETTINGS,SETTINGS+SETTINGS_SIZE]);}
ranges.push(...codeplug.customRanges);for(const[a,b]of ranges){target.set(codeplug.img.subarray(a,b),a);}
const sectors=[];for(const r of L.REGIONS){for(let s=r.start/L.SECTOR;s<r.end/L.SECTOR;s++){const a=s*L.SECTOR;if(target.subarray(a,a+L.SECTOR).some((v,i)=>v!==onRadio[a+i])){sectors.push(s);}}}
if(sectors.length===0){await link.closeScreen();status(t('nothingToWrite'));return;}
status(t('writing'));for(let i=0;i<sectors.length;i++){const a=sectors[i]*L.SECTOR;await link.writeSector(sectors[i],target.subarray(a,a+L.SECTOR));progress(i+1,sectors.length);}
await link.restart();status(t('writeDone')+` (${sectors.length} × 4 KB)`);toast(t('writeDone'));}catch(e){toast(t('error')+': '+e.message,6000);status(t('error'));}finally{progress(0,0);}}
function saveFile(){codeplug.store();const head=new TextEncoder().encode(FILE_MAGIC);const blob=new Blob([head,codeplug.img],{type:'application/octet-stream'});const a=el('a',{href:URL.createObjectURL(blob),download:(codeplug.general.callsign||'codeplug')+'.opendmr'});a.click();URL.revokeObjectURL(a.href);}
async function openFile(file){const data=new Uint8Array(await file.arrayBuffer());const head=new TextEncoder().encode(FILE_MAGIC);if((data.length!==head.length+L.IMAGE_SIZE)||!head.every((v,i)=>data[i]===v)){toast(t('badFile'));return;}
codeplug=new Codeplug(data.slice(head.length));selectedChannel=null;render();}
