function init(){document.querySelector('.side-foot').textContent='OpenDMR CPS · v'+VERSION;applyIcons();applyTexts();document.querySelectorAll('.tab').forEach((b)=>b.addEventListener('click',()=>{tab=b.dataset.tab;render();}));$('btnConnect').addEventListener('click',connect);$('btnRead').addEventListener('click',readRadio);$('btnWrite').addEventListener('click',writeRadio);$('btnSave').addEventListener('click',saveFile);$('btnOpen').addEventListener('click',()=>$('fileInput').click());$('fileInput').addEventListener('change',(e)=>{if(e.target.files[0]){openFile(e.target.files[0]);}
e.target.value='';});$('btnNew').addEventListener('click',()=>{codeplug=new Codeplug();selectedChannel=null;render();});$('btnLang').addEventListener('click',()=>{toggleLanguage();applyTexts();render();});render();}
init();